#!/usr/bin/env node
/**
 * Adds a release signing config to the Capacitor-generated Android project.
 *
 * `apps/android/android/` is git-ignored and regenerated by `cap add android`, so
 * the release workflow applies this patch after generating the platform, and only
 * when keystore secrets are configured. Without it `:app:assembleRelease` produces
 * an unsigned APK that cannot be installed.
 *
 * Usage:
 *   node apps/android/scripts/configure-release-signing.mjs \
 *     --keystore /path/to/release.jks --store-password "$STORE_PASSWORD" \
 *     --key-alias "$ALIAS" --key-password "$KEY_PASSWORD"
 */
import { chmodSync, existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { parseArgs } from "node:util";

const MARKER = "// --- release signing (configure-release-signing.mjs) ---";

const { values } = parseArgs({
  options: {
    project: { type: "string" },
    keystore: { type: "string" },
    "store-password": { type: "string" },
    "key-alias": { type: "string" },
    "key-password": { type: "string" },
  },
});

const required = ["keystore", "store-password", "key-alias", "key-password"];
for (const name of required) {
  if (!values[name]) {
    console.error(`Missing --${name}.`);
    process.exit(1);
  }
}

const shellDir = dirname(fileURLToPath(import.meta.url));
const projectRoot = resolve(values.project ?? join(shellDir, "..", "android"));
const gradleFile = join(projectRoot, "app", "build.gradle");
const keyPropertiesFile = join(projectRoot, "key.properties");

if (!existsSync(gradleFile)) {
  console.error(`Not a Capacitor Android project: ${gradleFile} does not exist.`);
  process.exit(1);
}

const keystorePath = resolve(values.keystore);
if (!existsSync(keystorePath)) {
  console.error(`Keystore not found: ${keystorePath}`);
  process.exit(1);
}

// java.util.Properties treats backslash as an escape character; newlines would
// break the file, so reject them instead of writing a corrupt keystore config.
const property = (value) => {
  if (/[\r\n]/.test(value)) {
    console.error("Keystore values must not contain newlines.");
    process.exit(1);
  }
  return value.replace(/\\/g, "\\\\");
};

writeFileSync(
  keyPropertiesFile,
  [
    `storeFile=${property(keystorePath)}`,
    `storePassword=${property(values["store-password"])}`,
    `keyAlias=${property(values["key-alias"])}`,
    `keyPassword=${property(values["key-password"])}`,
    "",
  ].join("\n"),
  "utf8",
);
chmodSync(keyPropertiesFile, 0o600);

const block = `${MARKER}
def keystorePropertiesFile = rootProject.file("key.properties")
if (keystorePropertiesFile.exists()) {
    def keystoreProperties = new Properties()
    keystorePropertiesFile.withInputStream { stream -> keystoreProperties.load(stream) }
    android {
        signingConfigs {
            release {
                storeFile file(keystoreProperties.getProperty("storeFile"))
                storePassword keystoreProperties.getProperty("storePassword")
                keyAlias keystoreProperties.getProperty("keyAlias")
                keyPassword keystoreProperties.getProperty("keyPassword")
            }
        }
        buildTypes {
            release {
                signingConfig signingConfigs.release
            }
        }
    }
}
`;

// Re-running must not stack duplicate blocks: drop anything from the marker on,
// which also covers a previous run on a freshly regenerated project.
const gradle = readFileSync(gradleFile, "utf8");
const base = gradle.split(MARKER)[0].trimEnd();
writeFileSync(gradleFile, `${base}\n\n${block}`, "utf8");

console.log(`Wrote ${keyPropertiesFile}`);
console.log(`Patched ${gradleFile} with a release signing config`);
